function validate([strings]) {
  if (!Array.isArray(strings) || strings.length < 1 || strings.length > 200) return 'strings needs 1 to 200 entries.';
  for (const s of strings) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 50) return 'Each string has 1 to 50 characters.';
    if (!/^[a-z]+$/.test(s)) return 'Strings use only lowercase English letters.';
  }
  return null;
}

