function groupStrings(strings) {
  const shift = (s, by) => s.split('').map(c => String.fromCharCode(97 + (c.charCodeAt(0) - 97 + by) % 26)).join('');
  const together = (a, b) => {
    if (a.length !== b.length) return false;
    for (let by = 0; by < 26; by++) if (shift(a, by) === b) return true;
    return false;
  };
  const result = [];
  for (const s of strings) {
    const group = result.find(g => together(g[0], s));
    if (group) group.push(s);
    else result.push([s]);
  }
  return result;
}

