function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const letters = (len, span) => Array.from({ length: len }, () => String.fromCharCode(97 + pick(span))).join('');
  const shift = (s, by) => s.split('').map(c => String.fromCharCode(97 + (c.charCodeAt(0) - 97 + by) % 26)).join('');
  const large = size === 'large';
  const n = large ? 200 : 1 + pick(8);
  const span = large || rand() < 0.5 ? 26 : 3;
  const bases = Array.from({ length: large ? 25 : 1 + pick(4) }, () => letters(1 + pick(large ? 50 : 3), span));
  const strings = [];
  for (let i = 0; i < n; i++) {
    if (rand() < 0.2) strings.push(letters(1 + pick(large ? 50 : 3), span));
    else strings.push(shift(bases[pick(bases.length)], pick(26)));
  }
  return [strings];
}
